import androidx.compose.ui.unit.dp

/**
 * Игровые силуэты из утверждённого набора Hunt Maps.
 * Одноцветные векторы сохраняют прорези, ткань и характерные формы объектов.
 * Векторные контуры не влияют на координаты и обработку нажатий.
 */
private fun huntGlyph(name: String, data: String): ImageVector = ImageVector.Builder(
    name = name,
    defaultWidth = 24.dp,
    defaultHeight = 24.dp,
    viewportWidth = 128f,
    viewportHeight = 128f
).apply {
    addPath(
        pathData = PathParser().parsePathString(data).toNodes(),
        fill = SolidColor(Color.White),
        pathFillType = PathFillType.EvenOdd
    )
}.build()

